static void rtl_fw_ver_erase(struct r8152 *tp)
{
	u16 outer_ver;
	u32 ocp_data;

	switch (tp->version) {
	case RTL_VER_01:
	case RTL_VER_02:
	case RTL_VER_03:
	case RTL_VER_04:
	case RTL_VER_05:
	case RTL_VER_06:
	case RTL_VER_07:
	case RTL_TEST_01:
		return;
	case RTL_VER_10:
	case RTL_VER_11:
	case RTL_VER_12:
	case RTL_VER_13:
	case RTL_VER_15:
		outer_ver = USB_OUTSIDE_FW_VER;
		break;
	default:
		outer_ver = USB_OUTER_FW_VER;
		break;
	}

	if (ocp_read_word(tp, MCU_TYPE_USB, outer_ver, &ocp_data) < 0)
		return;

	if (ocp_data) {
		ocp_write_word(tp, MCU_TYPE_USB, outer_ver, 0);
		ocp_write_word(tp, MCU_TYPE_USB, USB_FW_PLA_VER, 0);
	}
}
